    let b=&mut d[120..];b[..32].copy_from_slice(instance.as_ref());b[32..64].copy_from_slice(&business_for(BOOT,800_000+u64::from(primitive)));b[96..128].copy_from_slice(&catalog());b[128..160].copy_from_slice(&release_constants::VALIDATOR_HASH);b[160..164].copy_from_slice(&[1,0,primitive,if primitive==4{3}else{0}]);b[164..168].copy_from_slice(&1_000_000u32.to_le_bytes());b[168..176].copy_from_slice(&120_000u64.to_le_bytes());b[176..184].copy_from_slice(&45_000u64.to_le_bytes());b[184]=1;b[202..234].copy_from_slice(BOOT.as_ref());(key,Account{lamports:100_000_000,data:d,owner:PROGRAM,..Default::default()},instance)
