    std::fs::write(synthesis::evidence_dir().join("native-final-bound-result.txt"),format!("fixture_only=true\nasset_admission=false\ninput_capsule_bytes=3358\ninput_count=4\nverification_real_rounds=73\ntransaction_forced_rollback=true\nfinal_isolated_cu={isolated_cu}\ntransaction_cu={}\nverification_peak_cu={}\nheap=262144\n",result.compute_units_consumed,p.max_cu)).unwrap();
